:root {
  --bg: #06070d;
  --ink: #f7f1e4;
  --muted: #9b9aae;
  --dim: #6d6c80;
  --panel: rgba(16, 19, 32, 0.82);
  --panel-solid: #111522;
  --line: rgba(255, 255, 255, 0.09);
  --line-gold: rgba(255, 209, 102, 0.25);
  --gold: #ffd166;
  --gold-hot: #ffb72b;
  --gold-pale: #fff1b8;
  --pink: #ff5d8f;
  --pink-hot: #ff2e73;
  --cyan: #6ee7f9;
  --green: #78f2b1;
  --shadow: 0 24px 70px rgba(0, 0, 0, 0.55);
  --radius: 24px;
  --display: "Arial Black", "Trebuchet MS", "Avenir Next", sans-serif;
  --body: "Avenir Next", "Trebuchet MS", "Segoe UI", sans-serif;
}

* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
}

body {
  margin: 0;
  overflow: hidden;
  color: var(--ink);
  background:
    radial-gradient(circle at 20% 0%, rgba(86, 42, 98, 0.22), transparent 35%),
    radial-gradient(circle at 85% 15%, rgba(16, 92, 112, 0.16), transparent 35%),
    linear-gradient(180deg, #090b13 0%, #05060b 100%);
  font-family: var(--body);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button {
  font: inherit;
  color: inherit;
}

button,
canvas {
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}

.room-glow {
  position: fixed;
  width: 46vw;
  height: 46vw;
  border-radius: 50%;
  filter: blur(90px);
  opacity: 0.2;
  pointer-events: none;
  z-index: 0;
}

.room-glow--pink {
  top: -18vw;
  left: -10vw;
  background: #d82d78;
}

.room-glow--cyan {
  right: -15vw;
  bottom: -20vw;
  background: #158fa5;
}

.noise {
  position: fixed;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  opacity: 0.035;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.8'/%3E%3C/svg%3E");
}

.app {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  gap: 12px;
  width: min(1640px, 100%);
  height: 100dvh;
  margin: 0 auto;
  padding: 12px 16px 14px;
}

/* ---------- Header ---------- */

.topbar {
  display: grid;
  grid-template-columns: minmax(250px, 1fr) auto minmax(250px, 1fr);
  align-items: center;
  gap: 18px;
  min-height: 68px;
  flex: 0 0 auto;
}

.brand {
  display: flex;
  align-items: center;
  gap: 13px;
  min-width: 0;
}

.brand-emblem {
  position: relative;
  width: 52px;
  height: 52px;
  flex: 0 0 52px;
  filter: drop-shadow(0 8px 16px rgba(0, 0, 0, 0.45));
}

.emblem-coin {
  position: absolute;
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  color: #5c3600;
  font-family: var(--display);
  font-size: 15px;
  font-weight: 900;
  background:
    radial-gradient(circle at 34% 27%, #fff6c8 0 8%, transparent 9%),
    linear-gradient(145deg, #ffe589 2%, #ffc442 46%, #b66d05 100%);
  border: 2px solid #ffe99f;
  box-shadow:
    inset 0 0 0 3px rgba(123, 67, 0, 0.24),
    inset -4px -5px 8px rgba(126, 66, 0, 0.22),
    0 3px 0 #8e4f00,
    0 8px 16px rgba(0, 0, 0, 0.4);
}

.emblem-coin--back {
  left: 1px;
  top: 9px;
  transform: rotate(-18deg) scale(0.86);
  opacity: 0.65;
}

.emblem-coin--mid {
  left: 12px;
  top: 2px;
  transform: rotate(13deg) scale(0.92);
  opacity: 0.85;
}

.emblem-coin--front {
  left: 7px;
  top: 11px;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.brand-kicker {
  margin-bottom: -1px;
  color: var(--gold);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.34em;
  opacity: 0.8;
}

.brand h1 {
  margin: 0;
  font-family: var(--display);
  font-size: clamp(20px, 2vw, 29px);
  font-weight: 900;
  letter-spacing: -0.055em;
  line-height: 0.98;
  text-transform: uppercase;
  white-space: nowrap;
}

.brand h1 em {
  color: var(--gold);
  font-style: normal;
  text-shadow: 0 0 24px rgba(255, 209, 102, 0.35);
}

.brand-sub {
  margin-top: 4px;
  color: var(--muted);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.24em;
  white-space: nowrap;
}

.mode-tabs {
  display: flex;
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(11, 14, 24, 0.72);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.035), 0 10px 30px rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(18px);
}

.mode-tab {
  position: relative;
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: 46px;
  padding: 7px 18px 7px 11px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  cursor: pointer;
  overflow: hidden;
  transition: color 0.22s ease, background 0.22s ease, transform 0.22s ease;
}

.mode-tab:hover {
  background: rgba(255, 255, 255, 0.045);
}

.mode-tab.is-active {
  color: #221602;
  background:
    linear-gradient(180deg, rgba(255, 245, 194, 0.95), rgba(255, 194, 57, 0.98) 55%, rgba(235, 148, 13, 0.98));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    0 4px 0 rgba(125, 68, 0, 0.7),
    0 9px 24px rgba(255, 174, 33, 0.2);
}

.mode-tab.is-active:hover {
  background:
    linear-gradient(180deg, rgba(255, 250, 217, 1), rgba(255, 203, 77, 1) 55%, rgba(240, 155, 18, 1));
}

.tab-icon {
  display: grid;
  place-items: center;
  width: 31px;
  height: 31px;
  flex: 0 0 31px;
  border-radius: 50%;
  color: var(--gold);
  background: rgba(255, 209, 102, 0.11);
  border: 1px solid rgba(255, 209, 102, 0.16);
}

.mode-tab.is-active .tab-icon {
  color: #3a2300;
  background: rgba(78, 42, 0, 0.1);
  border-color: rgba(83, 45, 0, 0.12);
}

.tab-icon--pusher {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 2px;
  padding-bottom: 8px;
}

.tab-icon--pusher i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 -5px 0 -1px currentColor;
}

.tab-icon--pusher i:nth-child(2) {
  transform: translateY(-3px);
}

.tab-icon--claw svg {
  width: 19px;
  height: 19px;
}

.tab-copy {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  line-height: 1;
}

.tab-copy b {
  font-size: 12px;
  font-weight: 900;
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.tab-copy small {
  margin-top: 4px;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.1em;
  opacity: 0.62;
  text-transform: uppercase;
  white-space: nowrap;
}

.tab-glow {
  position: absolute;
  width: 50px;
  height: 50px;
  right: -10px;
  top: -20px;
  border-radius: 50%;
  background: #fff;
  filter: blur(22px);
  opacity: 0;
  transition: opacity 0.25s ease;
}

.mode-tab.is-active .tab-glow {
  opacity: 0.4;
}

.wallet-cluster {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  min-width: 0;
}

.wallet {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 54px;
  padding: 7px 15px 7px 9px;
  border: 1px solid var(--line-gold);
  border-radius: 16px;
  background:
    linear-gradient(135deg, rgba(255, 209, 102, 0.1), transparent 42%),
    rgba(12, 15, 25, 0.84);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 10px 30px rgba(0, 0, 0, 0.25);
  backdrop-filter: blur(18px);
}

.wallet-coin {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  color: #5d3500;
  background:
    radial-gradient(circle at 35% 26%, #fffbd9 0 8%, transparent 9%),
    linear-gradient(145deg, #ffeb9f, #ffc63e 48%, #b46b03);
  border: 2px solid #ffe99f;
  box-shadow: inset 0 0 0 3px rgba(116, 62, 0, 0.22), 0 3px 0 #8f5100;
}

.wallet-coin i {
  font-family: var(--display);
  font-size: 15px;
  font-style: normal;
  transform: translateY(-0.5px);
}

.wallet-copy {
  display: flex;
  flex-direction: column;
  line-height: 1;
}

.wallet-label {
  margin-bottom: 4px;
  color: var(--gold);
  font-size: 7px;
  font-weight: 900;
  letter-spacing: 0.18em;
}

.wallet strong {
  font-family: var(--display);
  font-size: 24px;
  font-weight: 900;
  letter-spacing: -0.04em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.wallet-pop {
  position: absolute;
  right: 14px;
  top: 5px;
  color: var(--green);
  font-family: var(--display);
  font-size: 12px;
  font-weight: 900;
  opacity: 0;
  pointer-events: none;
}

.wallet-pop.is-live {
  animation: wallet-pop 0.8s cubic-bezier(0.2, 0.8, 0.3, 1) both;
}

@keyframes wallet-pop {
  0% { opacity: 0; transform: translateY(6px) scale(0.8); }
  18% { opacity: 1; transform: translateY(-2px) scale(1.1); }
  70% { opacity: 1; transform: translateY(-10px) scale(1); }
  100% { opacity: 0; transform: translateY(-18px) scale(0.95); }
}

.icon-btn {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 14px;
  color: var(--muted);
  background: rgba(13, 16, 27, 0.72);
  cursor: pointer;
  transition: color 0.2s ease, background 0.2s ease, transform 0.2s ease;
}

.icon-btn:hover {
  color: var(--ink);
  background: rgba(255, 255, 255, 0.06);
  transform: translateY(-1px);
}

.icon-btn svg {
  width: 19px;
  height: 19px;
}

.icon-btn .sound-off {
  display: none;
}

.icon-btn.is-muted .sound-on {
  display: none;
}

.icon-btn.is-muted .sound-off {
  display: block;
}

.vault-mobile {
  display: none;
}

/* ---------- Main layout ---------- */

.main {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 308px;
  gap: 12px;
  flex: 1 1 auto;
  min-height: 0;
}

.play-area {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
  min-height: 0;
}

.stage {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: var(--radius);
  background:
    radial-gradient(circle at 50% 28%, rgba(46, 58, 86, 0.32), transparent 50%),
    linear-gradient(180deg, #0b0e18, #06070c);
  box-shadow:
    var(--shadow),
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    inset 0 0 80px rgba(0, 0, 0, 0.5);
  overflow: hidden;
  isolation: isolate;
}

.stage::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  border-radius: inherit;
  pointer-events: none;
  background:
    linear-gradient(115deg, rgba(255, 255, 255, 0.055), transparent 19%),
    radial-gradient(circle at 50% 100%, rgba(255, 175, 44, 0.05), transparent 44%);
}

.stage::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  border-radius: inherit;
  pointer-events: none;
  box-shadow: inset 0 0 0 1px rgba(255, 209, 102, 0.08);
}

#gameCanvas {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: crosshair;
}

.stage-ui {
  position: absolute;
  z-index: 4;
  display: flex;
  align-items: center;
  gap: 8px;
  pointer-events: none;
}

.stage-ui--top {
  top: 14px;
  left: 16px;
  right: 16px;
  justify-content: space-between;
}

.stage-ui--bottom {
  left: 16px;
  right: 16px;
  bottom: 12px;
  justify-content: space-between;
  opacity: 0.68;
}

.live-chip,
.mode-chip,
.aim-readout,
.ticker {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 0 9px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 999px;
  color: rgba(255, 255, 255, 0.55);
  background: rgba(7, 9, 16, 0.46);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.14em;
  backdrop-filter: blur(10px);
}

.live-chip {
  color: var(--green);
  border-color: rgba(120, 242, 177, 0.16);
  background: rgba(7, 20, 15, 0.48);
}

.live-chip i,
.panel-live i {
  width: 5px;
  height: 5px;
  margin-right: 6px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 8px currentColor;
  animation: live-pulse 1.8s ease-in-out infinite;
}

@keyframes live-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}

.mode-chip {
  color: var(--gold);
  border-color: rgba(255, 209, 102, 0.15);
}

.aim-readout {
  color: var(--gold);
  font-variant-numeric: tabular-nums;
}

.ticker {
  max-width: 48%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.hint {
  position: absolute;
  z-index: 6;
  left: 50%;
  top: 57px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 14px 9px 11px;
  border: 1px solid rgba(255, 209, 102, 0.24);
  border-radius: 999px;
  color: var(--gold-pale);
  background: rgba(14, 13, 12, 0.75);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.34), 0 0 30px rgba(255, 178, 36, 0.06);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.02em;
  white-space: nowrap;
  transform: translateX(-50%);
  transition: opacity 0.35s ease, transform 0.35s ease;
  backdrop-filter: blur(12px);
  pointer-events: none;
}

.hint-icon {
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  color: #5a3600;
  background: var(--gold);
  font-size: 10px;
}

.hint.is-hidden {
  opacity: 0;
  transform: translate(-50%, -8px);
}

.toast-stack {
  position: absolute;
  z-index: 9;
  top: 50px;
  right: 14px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 7px;
  width: min(260px, 52%);
  pointer-events: none;
}

.toast {
  display: flex;
  align-items: center;
  gap: 9px;
  max-width: 100%;
  padding: 9px 12px;
  border: 1px solid rgba(255, 209, 102, 0.2);
  border-radius: 11px;
  color: var(--ink);
  background: rgba(13, 15, 23, 0.9);
  box-shadow: 0 10px 26px rgba(0, 0, 0, 0.38);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.3;
  transform-origin: top right;
  animation: toast-in 0.3s cubic-bezier(0.2, 0.9, 0.3, 1.2) both;
  backdrop-filter: blur(12px);
}

.toast.is-out {
  animation: toast-out 0.3s ease both;
}

.toast b {
  color: var(--gold);
  font-weight: 900;
}

.toast-icon {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  flex: 0 0 22px;
  border-radius: 7px;
  color: #3d2600;
  background: var(--gold);
  font-size: 11px;
}

.toast--pink {
  border-color: rgba(255, 93, 143, 0.25);
}

.toast--pink .toast-icon {
  color: #3d0017;
  background: var(--pink);
}

.toast--cyan {
  border-color: rgba(110, 231, 249, 0.25);
}

.toast--cyan .toast-icon {
  color: #00272d;
  background: var(--cyan);
}

@keyframes toast-in {
  from { opacity: 0; transform: translateX(14px) scale(0.95); }
  to { opacity: 1; transform: translateX(0) scale(1); }
}

@keyframes toast-out {
  to { opacity: 0; transform: translateX(10px) scale(0.96); }
}

.big-win {
  position: absolute;
  z-index: 10;
  left: 50%;
  top: 44%;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: min(360px, 80%);
  padding: 18px 24px;
  border: 1px solid rgba(255, 209, 102, 0.4);
  border-radius: 20px;
  background:
    radial-gradient(circle at 50% 0%, rgba(255, 209, 102, 0.24), transparent 62%),
    rgba(10, 11, 18, 0.88);
  box-shadow: 0 0 0 8px rgba(255, 209, 102, 0.04), 0 30px 80px rgba(0, 0, 0, 0.6);
  opacity: 0;
  transform: translate(-50%, -50%) scale(0.7);
  pointer-events: none;
  backdrop-filter: blur(14px);
}

.big-win.is-live {
  animation: big-win 2.2s cubic-bezier(0.18, 0.9, 0.25, 1) both;
}

.big-win-kicker {
  color: var(--pink);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.3em;
}

.big-win strong {
  margin: 4px 0 2px;
  color: var(--gold);
  font-family: var(--display);
  font-size: clamp(42px, 8vw, 70px);
  font-weight: 900;
  letter-spacing: -0.06em;
  line-height: 1;
  text-shadow: 0 0 38px rgba(255, 193, 45, 0.45);
}

.big-win-sub {
  color: var(--muted);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.15em;
}

@keyframes big-win {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.7) rotate(-2deg); }
  12% { opacity: 1; transform: translate(-50%, -50%) scale(1.06) rotate(0.5deg); }
  20% { transform: translate(-50%, -50%) scale(1) rotate(0deg); }
  78% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
  100% { opacity: 0; transform: translate(-50%, -58%) scale(1.04); }
}

/* ---------- Control dock ---------- */

.control-dock {
  flex: 0 0 auto;
  padding: 9px 12px 10px;
  border: 1px solid var(--line);
  border-radius: 20px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.025), transparent 34%),
    rgba(13, 16, 27, 0.82);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.045), 0 15px 40px rgba(0, 0, 0, 0.25);
  backdrop-filter: blur(18px);
}

.denom-strip,
.claw-strip {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 38px;
  padding: 0 2px 8px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.denom-label {
  flex: 0 0 auto;
  color: var(--muted);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.16em;
}

.denom-options {
  display: flex;
  align-items: center;
  gap: 5px;
}

.denom {
  --coin-a: #ffd166;
  --coin-b: #b86d08;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  height: 28px;
  min-width: 53px;
  padding: 0 9px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  color: rgba(255, 255, 255, 0.58);
  background: rgba(255, 255, 255, 0.035);
  font-family: var(--display);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: -0.02em;
  cursor: pointer;
  transition: color 0.18s ease, border 0.18s ease, background 0.18s ease, transform 0.18s ease;
}

.denom i {
  display: grid;
  place-items: center;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  color: rgba(0, 0, 0, 0.5);
  background: linear-gradient(145deg, var(--coin-a), var(--coin-b));
  font-size: 7px;
  font-style: normal;
}

.denom[data-value="10"] { --coin-a: #f2b27b; --coin-b: #8f4a1f; }
.denom[data-value="20"] { --coin-a: #eef3fa; --coin-b: #7e8a9e; }
.denom[data-value="30"] { --coin-a: #ffe17a; --coin-b: #bd7a06; }
.denom[data-value="50"] { --coin-a: #ffb29a; --coin-b: #a8472e; }
.denom[data-value="100"] { --coin-a: #8ff4c6; --coin-b: #147a5a; }
.denom[data-value="200"] { --coin-a: #d3b7ff; --coin-b: #5e2aa6; }

.denom:hover {
  color: var(--ink);
  background: rgba(255, 255, 255, 0.07);
  transform: translateY(-1px);
}

.denom.is-selected {
  color: #241700;
  border-color: rgba(255, 235, 163, 0.9);
  background: linear-gradient(180deg, #fff4bd, #ffc43f 68%, #e79b17);
  box-shadow: inset 0 1px 0 #fffce6, 0 3px 0 #8d5000, 0 7px 18px rgba(255, 173, 25, 0.18);
}

.denom.is-selected i {
  color: #3b2200;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.15);
}

.denom.is-poor {
  opacity: 0.38;
}

.denom-note {
  margin-left: auto;
  color: var(--dim);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.05em;
  white-space: nowrap;
}

.claw-strip {
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
}

.claw-price {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--gold);
  font-family: var(--display);
  font-size: 15px;
  font-weight: 900;
}

.claw-strip-rule {
  width: 1px;
  height: 13px;
  background: var(--line);
}

.claw-note b {
  color: var(--gold-pale);
}

.dock-main {
  display: flex;
  align-items: center;
  gap: 16px;
  padding-top: 8px;
}

.dock-copy {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex: 1 1 auto;
}

.dock-eyebrow {
  color: var(--gold);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.17em;
}

.dock-hint {
  margin-top: 4px;
  overflow: hidden;
  color: var(--muted);
  font-size: 10px;
  font-weight: 600;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

kbd {
  padding: 1px 4px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 4px;
  color: var(--ink);
  background: rgba(255, 255, 255, 0.06);
  font-family: var(--body);
  font-size: 8px;
}

.primary-action {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  width: 216px;
  height: 58px;
  flex: 0 0 216px;
  padding: 0 16px;
  border: 1px solid #fff0a3;
  border-radius: 14px;
  color: #281800;
  background:
    radial-gradient(circle at 50% -20%, #fffde4, transparent 55%),
    linear-gradient(180deg, #fff1a7 0%, #ffcb4c 48%, #f1a117 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.9),
    inset 0 -3px 0 rgba(133, 73, 0, 0.18),
    0 5px 0 #8c5000,
    0 12px 30px rgba(255, 168, 24, 0.22);
  cursor: pointer;
  overflow: hidden;
  transition: transform 0.14s ease, box-shadow 0.14s ease, filter 0.2s ease;
}

.primary-action:hover {
  transform: translateY(-1px);
  filter: brightness(1.04);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.9),
    inset 0 -3px 0 rgba(133, 73, 0, 0.18),
    0 6px 0 #8c5000,
    0 16px 34px rgba(255, 168, 24, 0.3);
}

.primary-action:active {
  transform: translateY(4px);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.75),
    0 1px 0 #8c5000,
    0 6px 18px rgba(255, 168, 24, 0.2);
}

.primary-action.is-busy {
  cursor: wait;
  filter: saturate(0.7) brightness(0.9);
}

.primary-action.is-poor {
  color: #d9d3c8;
  border-color: rgba(255, 255, 255, 0.14);
  background: linear-gradient(180deg, #42414a, #26252d);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.12), 0 4px 0 #141319;
}

.action-copy {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  line-height: 1;
}

.action-main {
  font-family: var(--display);
  font-size: 17px;
  font-weight: 900;
  letter-spacing: -0.03em;
  text-transform: uppercase;
}

.action-cost {
  margin-top: 4px;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.12em;
  opacity: 0.65;
}

.action-arrow {
  display: grid;
  place-items: center;
  width: 25px;
  height: 25px;
  border-radius: 50%;
  background: rgba(52, 30, 0, 0.12);
  font-size: 15px;
  font-weight: 900;
}

.action-shine {
  position: absolute;
  top: -70%;
  left: -40%;
  width: 32%;
  height: 240%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.55), transparent);
  transform: rotate(22deg);
  animation: shine 4.6s ease-in-out infinite;
}

@keyframes shine {
  0%, 64% { left: -45%; }
  82%, 100% { left: 125%; }
}

.dock-meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  width: 100px;
  flex: 0 0 100px;
  line-height: 1;
}

.meta-label {
  color: var(--muted);
  font-size: 7px;
  font-weight: 900;
  letter-spacing: 0.15em;
}

.dock-meta strong {
  margin: 4px 0 3px;
  color: var(--gold);
  font-family: var(--display);
  font-size: 19px;
  font-weight: 900;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
}

.meta-sub {
  color: var(--dim);
  font-size: 8px;
  font-weight: 700;
}

/* ---------- Sidebar ---------- */

.sidebar {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-height: 0;
  overflow: hidden;
}

.panel {
  position: relative;
  border: 1px solid var(--line);
  border-radius: 19px;
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.03), transparent 38%),
    var(--panel);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04), 0 15px 40px rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(18px);
}

.stats-panel {
  padding: 15px;
}

.panel-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  color: var(--muted);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.17em;
}

.panel-live {
  display: inline-flex;
  align-items: center;
  color: var(--green);
  font-size: 7px;
  letter-spacing: 0.13em;
}

.panel-live i {
  width: 4px;
  height: 4px;
  margin-right: 5px;
}

.stat-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  margin-top: 12px;
}

.stat {
  display: flex;
  flex-direction: column;
  min-height: 59px;
  padding: 9px 10px;
  border: 1px solid rgba(255, 255, 255, 0.055);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.025);
}

.stat-label {
  color: var(--dim);
  font-size: 7px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.stat strong {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 7px;
  color: var(--ink);
  font-family: var(--display);
  font-size: 18px;
  font-weight: 900;
  letter-spacing: -0.03em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.stat:nth-child(1) strong {
  color: var(--gold);
}

.mini-coin {
  display: inline-grid;
  place-items: center;
  width: 13px;
  height: 13px;
  flex: 0 0 13px;
  border-radius: 50%;
  color: #573200;
  background: linear-gradient(145deg, #ffeda0, #f8b52e);
  font-family: var(--display);
  font-size: 7px;
  font-weight: 900;
  box-shadow: inset 0 0 0 1px rgba(112, 61, 0, 0.25);
}

.win-meter {
  margin-top: 12px;
}

.win-meter-copy {
  display: flex;
  justify-content: space-between;
  color: var(--dim);
  font-size: 7px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.win-meter-copy span:last-child {
  color: var(--gold);
  letter-spacing: 0.02em;
}

.win-meter-track {
  height: 5px;
  margin-top: 6px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  overflow: hidden;
}

.win-meter-track i {
  display: block;
  width: 50%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #ff7f4f, #ffd166 55%, #6ee7f9);
  box-shadow: 0 0 12px rgba(255, 209, 102, 0.4);
  transition: width 0.6s cubic-bezier(0.2, 0.8, 0.3, 1);
}

.vault-panel {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-height: 170px;
  padding: 15px;
  overflow: hidden;
}

.text-btn {
  padding: 0;
  border: 0;
  color: var(--gold);
  background: transparent;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: 0.12em;
  cursor: pointer;
}

.text-btn:hover {
  color: var(--gold-pale);
}

.prize-shelf {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  margin-top: 12px;
  min-height: 104px;
  overflow: hidden;
}

.vault-empty {
  grid-column: 1 / -1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 104px;
  border: 1px dashed rgba(255, 255, 255, 0.1);
  border-radius: 11px;
  color: var(--dim);
  text-align: center;
}

.vault-empty .empty-spark {
  color: rgba(255, 209, 102, 0.5);
  font-size: 20px;
  line-height: 1;
}

.vault-empty p {
  margin: 6px 0 0;
  font-size: 9px;
  font-weight: 700;
  line-height: 1.4;
}

.shelf-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  padding: 7px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.028);
  animation: shelf-in 0.4s cubic-bezier(0.2, 0.8, 0.3, 1.2) both;
}

@keyframes shelf-in {
  from { opacity: 0; transform: scale(0.88); }
  to { opacity: 1; transform: scale(1); }
}

.shelf-icon {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  flex: 0 0 30px;
  border-radius: 8px;
  background: var(--prize-bg, rgba(255, 209, 102, 0.12));
  font-size: 17px;
  line-height: 1;
  filter: drop-shadow(0 3px 5px rgba(0, 0, 0, 0.25));
}

.shelf-copy {
  display: flex;
  flex-direction: column;
  min-width: 0;
  line-height: 1;
}

.shelf-name {
  overflow: hidden;
  color: var(--ink);
  font-size: 8px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.shelf-value {
  display: flex;
  align-items: center;
  gap: 3px;
  margin-top: 4px;
  color: var(--gold);
  font-family: var(--display);
  font-size: 9px;
  font-weight: 900;
}

.shelf-value .mini-coin {
  width: 9px;
  height: 9px;
  flex-basis: 9px;
  font-size: 5px;
}

.vault-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: auto;
  padding-top: 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.055);
  color: var(--dim);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.vault-foot span:last-child {
  letter-spacing: 0.12em;
  white-space: nowrap;
}

.legend-dot {
  display: inline-block;
  width: 5px;
  height: 5px;
  margin-right: 4px;
  border-radius: 50%;
  vertical-align: 1px;
}

.legend-dot--gold {
  background: var(--gold);
  box-shadow: 0 0 7px rgba(255, 209, 102, 0.7);
}

.tip-panel {
  display: flex;
  gap: 12px;
  flex: 0 0 auto;
  min-height: 120px;
  padding: 15px;
  overflow: hidden;
  background:
    radial-gradient(circle at 100% 0%, rgba(255, 93, 143, 0.15), transparent 55%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.03), transparent 38%),
    var(--panel);
}

.tip-panel::after {
  content: "";
  position: absolute;
  right: -22px;
  bottom: -36px;
  width: 90px;
  height: 90px;
  border: 1px solid rgba(255, 93, 143, 0.18);
  border-radius: 50%;
}

.tip-mark {
  flex: 0 0 35px;
  color: rgba(255, 93, 143, 0.7);
  font-family: var(--display);
  font-size: 26px;
  font-weight: 900;
  letter-spacing: -0.08em;
  line-height: 1;
}

.tip-copy {
  position: relative;
  z-index: 1;
  min-width: 0;
}

.tip-kicker {
  color: var(--pink);
  font-size: 7px;
  font-weight: 900;
  letter-spacing: 0.18em;
}

.tip-copy h2 {
  margin: 5px 0 4px;
  font-family: var(--display);
  font-size: 15px;
  font-weight: 900;
  letter-spacing: -0.03em;
  line-height: 1.05;
}

.tip-copy p {
  margin: 0;
  color: var(--muted);
  font-size: 9px;
  font-weight: 600;
  line-height: 1.45;
}

.free-coins {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 0 0 auto;
  width: 100%;
  padding: 10px 12px;
  border: 1px solid rgba(255, 209, 102, 0.28);
  border-radius: 15px;
  color: var(--ink);
  background:
    linear-gradient(135deg, rgba(255, 209, 102, 0.15), transparent 55%),
    rgba(20, 17, 12, 0.9);
  text-align: left;
  cursor: pointer;
  animation: free-in 0.3s ease both;
}

.free-coins[hidden] {
  display: none;
}

@keyframes free-in {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

.free-coins-icon {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  border-radius: 50%;
  color: #4a2a00;
  background: var(--gold);
  font-size: 13px;
}

.free-coins > span:nth-child(2) {
  display: flex;
  flex-direction: column;
  line-height: 1;
}

.free-coins b {
  font-size: 9px;
  font-weight: 900;
}

.free-coins small {
  margin-top: 4px;
  color: var(--muted);
  font-size: 8px;
}

.free-coins-arrow {
  margin-left: auto;
  color: var(--gold);
  font-size: 17px;
}

/* ---------- Modal ---------- */

.modal {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  padding: 20px;
}

.modal[hidden] {
  display: none;
}

.modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(3, 4, 8, 0.78);
  backdrop-filter: blur(10px);
  animation: fade-in 0.25s ease both;
}

.modal-card {
  position: relative;
  z-index: 1;
  width: min(680px, 100%);
  max-height: min(84dvh, 780px);
  padding: 28px;
  border: 1px solid rgba(255, 209, 102, 0.24);
  border-radius: 26px;
  background:
    radial-gradient(circle at 0% 0%, rgba(255, 93, 143, 0.13), transparent 40%),
    radial-gradient(circle at 100% 100%, rgba(110, 231, 249, 0.08), transparent 45%),
    #0d101a;
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.7), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  overflow: auto;
  animation: modal-in 0.35s cubic-bezier(0.2, 0.9, 0.25, 1.1) both;
}

@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes modal-in {
  from { opacity: 0; transform: translateY(18px) scale(0.96); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.modal-close {
  position: absolute;
  top: 15px;
  right: 15px;
  display: grid;
  place-items: center;
  width: 35px;
  height: 35px;
  border: 1px solid var(--line);
  border-radius: 50%;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.04);
  font-size: 21px;
  line-height: 1;
  cursor: pointer;
}

.modal-close:hover {
  color: var(--ink);
  background: rgba(255, 255, 255, 0.08);
}

.modal-head {
  padding-right: 40px;
}

.modal-kicker {
  color: var(--pink);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.24em;
}

.modal-head h2 {
  margin: 6px 0 7px;
  font-family: var(--display);
  font-size: clamp(28px, 4vw, 40px);
  font-weight: 900;
  letter-spacing: -0.05em;
  line-height: 1;
}

.modal-head p {
  max-width: 480px;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.5;
}

.modal-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 20px 0;
}

.modal-stats > div {
  display: flex;
  flex-direction: column;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.03);
}

.modal-stats span {
  color: var(--dim);
  font-size: 7px;
  font-weight: 900;
  letter-spacing: 0.13em;
}

.modal-stats strong {
  margin-top: 6px;
  color: var(--gold);
  font-family: var(--display);
  font-size: 21px;
  font-weight: 900;
  letter-spacing: -0.04em;
}

.modal-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.modal-item {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 104px;
  padding: 10px 7px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.028);
  text-align: center;
}

.modal-item-icon {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  border-radius: 14px;
  background: var(--prize-bg, rgba(255, 209, 102, 0.12));
  font-size: 27px;
  filter: drop-shadow(0 5px 8px rgba(0, 0, 0, 0.3));
}

.modal-item b {
  font-size: 9px;
  font-weight: 800;
}

.modal-item span:last-child {
  color: var(--gold);
