    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(30, freq), t);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), t + dur);
    gain.gain.setValueAtTime(0.0001, t);
